import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`app-builder`,heroTitle:`Build your app in minutes`,heroSubtitle:`Perplexity Computer turns a rough product brief into user flows, screen specs, data models, and a build plan your team can ship from.`,inputUrlCta:`Plan my app`,inputUrlPlaceholder:`e.g. notion.so/spec or figma.com/file/...`,inputUrlPrefill:`Go to {url} and turn it into a complete app build plan. (1) Analyze the product concept, target user, and primary workflow. (2) Define the core user journeys, screen list, navigation, and edge cases. (3) Recommend the data model, integrations, permissions, and analytics events needed for launch. (4) Draft the first-release scope, milestones, and technical handoff for design and engineering. (5) Deliver a share-ready package with requirements, launch risks, and prioritized next steps.`,heroOverlaySteps:[`Reviewing the concept, user, and core product workflow`,`Mapping the key screens, navigation, and edge cases`,`Defining the data model, integrations, and launch scope`,`Product spec and build plan ready for the team to use`],generatingSteps:[`Reading {url} to understand the concept, users, and product constraints`,`Designing an agent to map flows, screen requirements, and dependencies`,`Configuring the data model, integrations, and release scope`,`Packaging the work into a clean product and engineering handoff`],featureSectionTitle:`From rough concept to build-ready scope`,featureCardTitles:[`Connects to your product workflow`,`Outputs your team can build from`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Notion, Figma, Jira, GitHub, and Docs stay in the loop so requirements, specs, and handoffs move straight into your team workflow.`,`User journeys. Screen specs. Data model recommendations. Launch scope. Computer gives your team a concrete plan instead of a loose brainstorm.`],capabilitySectionTitle:`Your app planner, on demand`,capabilitySectionSubtitle:`Share the concept, step away, and come back to a scoped app plan your team can execute.`,capabilityCards:[{title:`Concept Review`,description:`Computer can absorb the concept, target user, and product goals so the plan starts from the right constraints and priorities.`},{title:`User Flow Design`,description:`Computer can map the main journeys, supporting screens, and edge cases so the product structure is clear before building starts.`},{title:`Technical Scope`,description:`Computer can define the data model, integrations, permissions, and analytics events needed for a practical first release.`},{title:`Connect Your Tools`,description:`Computer can package the work into Figma notes, Docs, Jira tickets, and GitHub-ready handoffs so the team can move quickly.`},{title:`Release Planning`,description:`Computer can turn the scope into milestones, dependencies, and launch risks so the first release is easier to sequence.`},{title:`Iteration Support`,description:`Computer can revisit the product later, refine the scope, and adjust the plan as feedback or constraints change.`}]});export{t as default};
